 @Composable private fun Shell(logout:()->Unit){var tab by remember{mutableStateOf("Home")};var e by remember{mutableStateOf(emptyList<Employee>())};var d by remember{mutableStateOf(emptyList<Device>())};var a by remember{mutableStateOf(emptyList<Attendance>())};var s by remember{mutableStateOf(Summary(0,0,0,0,0,"0h 0m"))};var refresh by remember{mutableStateOf(0)};LaunchedEffect(refresh){loadEmployees{e=it};loadDevices{d=it};loadAttendance("","",""){x,y->a=x;s=y}};Scaffold(bottomBar={NavigationBar{listOf("Home","Staff","Attendance","Devices","More").forEach{n->NavigationBarItem(selected=tab==n,onClick={tab=n},icon={Text(n.first().toString())},label={Text(n)})}}}){p->Column(Modifier.fillMaxSize().padding(p).padding(18.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("ATTEND",fontSize=28.sp,fontWeight=FontWeight.Bold);Text("Admin control center",color=Color.Gray)};TextButton({refresh++}){Text("SYNC")}};Spacer(Modifier.height(12.dp));when(tab){"Home"->Home(e,d,a,s);"Staff"->Staff(e){refresh++};"Attendance"->AttendanceScreen(e,a,s){f,t,id->loadAttendance(f,t,id){x,y->a=x;s=y}};"Devices"->Devices(d,e){refresh++};else->More(logout)}}}}
