 @Composable private fun Staff(list:List<Employee>,reload:()->Unit){var open by remember{mutableStateOf(false)};var q by remember{mutableStateOf("")};var detail by remember{mutableStateOf<Employee?>(null)};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("Staff",fontSize=25.sp,fontWeight=FontWeight.Bold);Text("${list.size} employees",color=Color.Gray)};Button({open=true}){Text("+ ADD")}};Spacer(Modifier.height(8.dp));OutlinedTextField(q,{q=it},label={Text("Search staff")},singleLine=true,modifier=Modifier.fillMaxWidth());LazyColumn{items(list.filter{it.name.contains(q,true)||it.code.contains(q,true)||it.department.orEmpty().contains(q,true)}){x->Card(Modifier.fillMaxWidth().padding(vertical=4.dp),shape=RoundedCornerShape(16.dp),onClick={detail=x}){Row(Modifier.fillMaxWidth().padding(16.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(x.name,fontWeight=FontWeight.Bold);Text("${x.code} • ${x.department.orEmpty().ifBlank{"No department"}}",color=Color.Gray)};Text(if(x.active)"ACTIVE"else"INACTIVE",fontSize=11.sp)}}}}};if(open)AddEmployee({open=false},reload);detail?.let{EmployeeDialog(it){detail=null}}}
 @Composable private fun AddEmployee(close:()->Unit,reload:()->Unit){var code by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};var dept by remember{mutableStateOf("")};var photo by remember{mutableStateOf<Uri?>(null)};var status by remember{mutableStateOf("")};photoChanged={photo=selectedPhoto};AlertDialog(onDismissRequest=close,title={Text("Add staff")},text={Column{OutlinedTextField(code,{code=it},label={Text("Employee ID")});OutlinedTextField(name,{name=it},label={Text("Full name")});OutlinedTextField(dept,{dept=it},label={Text("Department")});Spacer(Modifier.height(8.dp));OutlinedButton({picker.launch("image/*")}){Text(if(photo==null)"Select face photo"else"Face photo selected")};if(status.isNotBlank())Text(status)}},confirmButton={Button(enabled=code.isNotBlank()&&name.isNotBlank()&&photo!=null,onClick={status="Enrolling face…";createEmployee(code,name,dept,photo!!){ok,t->status=t;if(ok){reload();close()}}}){Text("CREATE")}},dismissButton={TextButton(close){Text("CANCEL")}})}
