 @Composable private fun AttendanceScreen(employees:List<Employee>,list:List<Attendance>,s:Summary,search:(String,String,String)->Unit){var employee by remember{mutableStateOf<Employee?>(null)};var from by remember{mutableStateOf(LocalDate.now().withDayOfMonth(1).toString())};var to by remember{mutableStateOf(LocalDate.now().toString())};var choose by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize()){Text("Attendance",fontSize=25.sp,fontWeight=FontWeight.Bold);Text("View attendance by staff with FROM / TO dates",color=Color.Gray);Spacer(Modifier.height(12.dp));OutlinedButton({choose=true},Modifier.fillMaxWidth()){Text(employee?.let{"${it.name} • ${it.code}"}?:"ALL STAFF")};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({pickDate(from){from=it}},Modifier.weight(1f)){Text("FROM\n$from")};OutlinedButton({pickDate(to){to=it}},Modifier.weight(1f)){Text("TO\n$to")}};Button({search(from,to,employee?.id.orEmpty())},Modifier.fillMaxWidth()){Text("VIEW ATTENDANCE")};Spacer(Modifier.height(10.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Stat("Events",s.events.toString());Stat("IN",s.ins.toString());Stat("OUT",s.outs.toString())};Spacer(Modifier.height(10.dp));LazyColumn{items(list){AttendanceCard(it)}}};if(choose)EmployeePicker(employees,{employee=it;choose=false},{choose=false})}
