 @Composable private fun Devices(list:List<Device>,employees:List<Employee>,reload:()->Unit){var create by remember{mutableStateOf(false)};var assign by remember{mutableStateOf<Device?>(null)};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("Devices",fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Attendance terminals",color=Color.Gray)};Button({create=true}){Text("+ ADD DEVICE")}};Spacer(Modifier.height(8.dp));LazyColumn{items(list){d->DeviceCard(d,{assign=d},true)}}};if(create)CreateDevice({create=false},reload);assign?.let{AssignDialog(it,employees,{assign=null},reload)}}
 @Composable private fun DeviceCard(d:Device,click:()->Unit,manage:Boolean){Card(Modifier.fillMaxWidth().padding(vertical=5.dp),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(d.name,fontSize=18.sp,fontWeight=FontWeight.Bold);Text(d.id.take(8),color=Color.Gray)};Text("● ${d.status.uppercase()}",fontSize=11.sp)};d.lastSeen?.takeIf{it.isNotBlank()}?.let{Text("Last seen $it")};d.pairingCode?.takeIf{it.isNotBlank()}?.let{Text("PAIRING CODE  $it",fontSize=18.sp,fontWeight=FontWeight.Bold);TextButton({copyCode(it)}){Text("COPY CODE")}};if(manage)Button(click){Text("MANAGE STAFF")}}}}
 @Composable private fun CreateDevice(close:()->Unit,reload:()->Unit){var name by remember{mutableStateOf("")};var code by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Create attendance device")},text={Column{Text("A one-time code will connect the Attendance app to this device.");OutlinedTextField(name,{name=it},label={Text("Device name")});if(code.isNotBlank()){Spacer(Modifier.height(10.dp));Text("PAIRING CODE",fontSize=11.sp);Text(code,fontSize=34.sp,fontWeight=FontWeight.Bold);Text("Enter this exact code in the Attendance app.");TextButton({copyCode(code)}){Text("COPY")}}}},confirmButton={Button(enabled=name.isNotBlank()&&code.isBlank(),onClick={createDevice(name){code=it;reload()}}){Text("GENERATE CODE")}},dismissButton={TextButton(close){Text(if(code.isBlank())"CLOSE"else"DONE")}})}
 @Composable private fun AssignDialog(d:Device,employees:List<Employee>,close:()->Unit,reload:()->Unit){var selected by remember{mutableStateOf(setOf<String>())};var loading by remember{mutableStateOf(true)};LaunchedEffect(d.id){loadAssignments(d.id){selected=it;loading=false}};AlertDialog(onDismissRequest=close,title={Text("Manage staff")},text={Column{Text(d.name,fontWeight=FontWeight.Bold);if(loading)Text("Loading assignments…");LazyColumn(Modifier.heightIn(max=400.dp)){items(employees){e->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Checkbox(selected.contains(e.id),{selected=if(it)selected+e.id else selected-e.id});Text("${e.name} • ${e.code}")}}}}},confirmButton={Button({assign(d.id,selected.toList()){reload();close()}}){Text("SAVE")}},dismissButton={TextButton(close){Text("CANCEL")}})}
 @Composable private fun More(logout:()->Unit){Column(Modifier.fillMaxSize()){Text("More",fontSize=25.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(8.dp));MoreRow("Business","Current business and access");MoreRow("Reports","Attendance exports and summaries");MoreRow("Notifications","Live attendance and device alerts");MoreRow("Security","Admin and device authentication");MoreRow("Settings","Application preferences");Spacer(Modifier.height(18.dp));OutlinedButton(logout,Modifier.fillMaxWidth()){Text("LOG OUT")}}}
 @Composable private fun MoreRow(a:String,b:String){Card(Modifier.fillMaxWidth().padding(vertical=4.dp),shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(16.dp)){Text(a,fontWeight=FontWeight.Bold);Text(b,color=Color.Gray)}}}
 private fun login(email:String,password:String,done:(Boolean,String)->Unit)=executor.execute{try{val b=JSONObject().put("email",email).put("password",password).toString().toRequestBody("application/json".toMediaType());http.newCall(Request.Builder().url("$baseUrl/api/v1/admin/login").post(b).build()).execute().use{r->if(!r.isSuccessful)throw Exception("Login failed (${r.code})");token=JSONObject(r.body?.string()?:"{}").getString("token")};getSharedPreferences("admin",0).edit().putString("token",token).apply();runOnUiThread{done(true,"Logged in")}}catch(e:Exception){runOnUiThread{done(false,e.message?:"Login failed")}}}
 private fun call(path:String):String{val r=http.newCall(Request.Builder().url(baseUrl+path).header("Authorization","Bearer $token").get().build()).execute();if(!r.isSuccessful)throw Exception("HTTP ${r.code}");return r.body?.string()?:"{}"}
 private fun loadEmployees(done:(List<Employee>)->Unit)=executor.execute{try{val a=JSONObject(call("/api/v1/admin/employees")).getJSONArray("items");val o=List(a.length()){i->val x=a.getJSONObject(i);Employee(x.getString("id"),x.getString("employee_code"),x.getString("name"),x.optString("department").ifBlank{null},x.optBoolean("active",true))};runOnUiThread{done(o)}}catch(_:Exception){}}
 private fun loadDevices(done:(List<Device>)->Unit)=executor.execute{try{val a=JSONObject(call("/api/v1/admin/devices")).getJSONArray("items");val o=List(a.length()){i->val x=a.getJSONObject(i);Device(x.getString("id"),x.getString("name"),x.getString("status"),x.optString("pairing_code").ifBlank{null},x.optString("last_seen_at").ifBlank{null})};runOnUiThread{done(o)}}catch(_:Exception){}}
 private fun loadAttendance(from:String,to:String,id:String,done:(List<Attendance>,Summary)->Unit)=executor.execute{try{val q=if(from.isBlank())""else"?from=$from&to=$to${if(id.isBlank())""else"&employeeId=$id"}";val j=JSONObject(call("/api/v1/admin/attendance$q"));val a=j.getJSONArray("items");val o=List(a.length()){i->val x=a.getJSONObject(i);Attendance(if(x.isNull("employee_id"))null else x.getString("employee_id"),x.getString("employee_name"),x.getString("employee_code"),x.getString("status"),x.getString("captured_at"),x.getString("device_name"),x.optString("photo_secure_url").ifBlank{null})};val z=j.optJSONObject("summary");val sum=Summary(z?.optInt("events",o.size)?:o.size,z?.optInt("ins",0)?:0,z?.optInt("outs",0)?:0,z?.optInt("presentDays",0)?:0,z?.optInt("absentDays",0)?:0,z?.optString("hours","0h 0m")?:"0h 0m");runOnUiThread{done(o,sum)}}catch(_:Exception){}}
 private fun createDevice(name:String,done:(String)->Unit)=executor.execute{try{val b=JSONObject().put("name",name).toString().toRequestBody("application/json".toMediaType());http.newCall(Request.Builder().url("$baseUrl/api/v1/admin/devices").header("Authorization","Bearer $token").post(b).build()).execute().use{r->if(!r.isSuccessful)throw Exception("Create failed ${r.code}");val x=JSONObject(r.body?.string()?:"{}").getJSONObject("device");runOnUiThread{done(x.getString("pairing_code"))}}}catch(e:Exception){runOnUiThread{done("ERROR")}}}
 private fun loadAssignments(id:String,done:(Set<String>)->Unit)=executor.execute{try{val a=JSONObject(call("/api/v1/admin/devices/$id/assignments")).getJSONArray("employeeIds");runOnUiThread{done(buildSet{for(i in 0 until a.length())add(a.getString(i))})}}catch(_:Exception){runOnUiThread{done(emptySet())}}}
 private fun assign(id:String,ids:List<String>,done:()->Unit)=executor.execute{try{val a=JSONArray();ids.forEach{a.put(it)};val b=JSONObject().put("employeeIds",a).toString().toRequestBody("application/json".toMediaType());http.newCall(Request.Builder().url("$baseUrl/api/v1/admin/devices/$id/assign").header("Authorization","Bearer $token").post(b).build()).execute().use{r->if(!r.isSuccessful)throw Exception("Assign failed ${r.code}")};runOnUiThread(done)}catch(_:Exception){}}
 private fun createEmployee(code:String,name:String,dept:String,uri:Uri,done:(Boolean,String)->Unit){executor.execute{try{val bmp=contentResolver.openInputStream(uri)?.use{BitmapFactory.decodeStream(it)}?:throw Exception("Invalid image");val detector=FaceDetection.getClient(FaceDetectorOptions.Builder().setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_ACCURATE).build());detector.process(InputImage.fromBitmap(bmp,0)).addOnSuccessListener{faces->if(faces.size!=1){runOnUiThread{done(false,if(faces.isEmpty())"No face detected"else"Use a photo with one face")};return@addOnSuccessListener};val t=template(bmp,faces[0].boundingBox)?:run{runOnUiThread{done(false,"Face enrollment failed")};return@addOnSuccessListener};executor.execute{try{val a=JSONArray();t.forEach{a.put(it.toDouble())};val b=JSONObject().put("employeeCode",code).put("name",name).put("department",dept).put("faceTemplate",a).toString().toRequestBody("application/json".toMediaType());http.newCall(Request.Builder().url("$baseUrl/api/v1/admin/employees").header("Authorization","Bearer $token").post(b).build()).execute().use{r->if(!r.isSuccessful)throw Exception("Create failed (${r.code})")};runOnUiThread{done(true,"Employee created")}}catch(e:Exception){runOnUiThread{done(false,e.message?:"Create failed")}}}}.addOnFailureListener{runOnUiThread{done(false,"Face detection failed")}}}catch(e:Exception){runOnUiThread{done(false,e.message?:"Photo error")}}}}
 private fun template(src:Bitmap,box:Rect):FloatArray?{val p=(box.width()*.18f).toInt();val l=(box.left-p).coerceAtLeast(0);val t=(box.top-p).coerceAtLeast(0);val r=(box.right+p).coerceAtMost(src.width);val b=(box.bottom+p).coerceAtMost(src.height);if(r<=l||b<=t)return null;val s=Bitmap.createScaledBitmap(Bitmap.createBitmap(src,l,t,r-l,b-t),32,32,true);val a=FloatArray(1024);var k=0;var m=0f;for(y in 0..31)for(x in 0..31){val c=s.getPixel(x,y);val v=(.299f*((c shr 16)and 255)+.587f*((c shr 8)and 255)+.114f*(c and 255))/255f;a[k++]=v;m+=v};m/=1024f;var n=0f;for(i in a.indices){a[i]-=m;n+=a[i]*a[i]};n=sqrt(n).coerceAtLeast(.0001f);for(i in a.indices)a[i]/=n;return a}
 private fun copyCode(code:String){(getSystemService(Context.CLIPBOARD_SERVICE)as ClipboardManager).setPrimaryClip(ClipData.newPlainText("Pairing code",code))}
}
